const BASE = 'https://n8n.checkintrust.com/webhook';
const EXT_TOKEN = (process.env && process.env.EDL_WEBHOOK_SECRET) || 'edl_wh_7Kx2mPn9sRtL';
const DOCUSEAL_TOKEN = (process.env && process.env.EDL_DOCUSEAL_TOKEN) || 'FtrjsZSaBdPdeZBTdhxbRTTXUMwV5gh6WFNqbBCbZTu';

const results = [];

async function test(name, fn) {
  try {
    await fn();
    results.push({ test: name, status: 'PASS' });
  } catch (e) {
    results.push({ test: name, status: 'FAIL', error: e.message });
  }
}

// T1: Agent 0 — accessible avec token valide
await test('Agent 0 — Token valide → liste retournée', async () => {
  const r = await fetch(`${BASE}/edl-locataires?t=${EXT_TOKEN}`);
  if (!r.ok) throw new Error(`HTTP ${r.status} ${r.statusText}`);
  const data = await r.json();
  if (!Array.isArray(data)) throw new Error('Format invalide : tableau attendu');
  if (data.length === 0) throw new Error('Liste vide — vérifier Notion');
});

// T2: Agent 0 — rejet sans token
await test('Agent 0 — Token manquant → 401', async () => {
  const r = await fetch(`${BASE}/edl-locataires`);
  if (r.status !== 401) throw new Error(`Attendu 401, reçu ${r.status}`);
});

// T3: Agent 6 — rejet token invalide
await test('Agent 6 — Token invalide → 401', async () => {
  const r = await fetch(`${BASE}/edl-secure`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ _token: 'MAUVAIS_TOKEN', meta: {}, pieces: {} })
  });
  if (r.status !== 401) throw new Error(`Attendu 401, reçu ${r.status}`);
});

// T4: Agent 6 — rejet schéma invalide (token ok mais schéma ko)
await test('Agent 6 — Schéma invalide → 401', async () => {
  const r = await fetch(`${BASE}/edl-secure`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ _token: EXT_TOKEN, meta: { type: 'INVALIDE', chambre: 999 }, pieces: {} })
  });
  if (r.status !== 401) throw new Error(`Attendu 401, reçu ${r.status}`);
});

// T5: DocuSeal — API accessible
await test('DocuSeal — API accessible', async () => {
  const r = await fetch('https://docuseal.checkintrust.com/api/templates?limit=1', {
    headers: { 'X-Auth-Token': DOCUSEAL_TOKEN }
  });
  if (!r.ok) throw new Error(`HTTP ${r.status} ${r.statusText}`);
});

const passed = results.filter(r => r.status === 'PASS').length;
const total = results.length;
return [{ json: {
  summary: `${passed}/${total} tests passés`,
  passed, total,
  allPassed: passed === total,
  results,
  timestamp: new Date().toISOString()
} }];
